/* Flash cards USMLE: Endocrinology (420 cartões originais). [id, pergunta, resposta, explicação em português] */
window.USMLE_DATA = window.USMLE_DATA || {};
window.USMLE_DATA["endocrinology"] = [{"name":"Anatomy","cards":[["v925wu35d","What are the three zones of the adrenal cortex from outside in?","Zona glomerulosa, zona fasciculata, zona reticularis. Mnemonic: GFR (salt, sugar, sex).","Glomerulosa, fasciculada, reticulada."],["pu02qg1hx","What does the zona glomerulosa produce and what regulates it?","Mineralocorticoids (aldosterone); regulated by renin-angiotensin-aldosterone system and K+.","Aldosterona; renina e potássio."],["17w4yuqiv","What does the zona fasciculata produce and what regulates it?","Glucocorticoids (cortisol); regulated by ACTH and CRH.","Cortisol; ACTH."],["1n7thnf5x","What does the zona reticularis produce and what regulates it?","Androgens (DHEA); regulated by ACTH and CRH.","Androgênios; ACTH."],["1ajlktt1g","What does the adrenal medulla produce and what regulates it?","Catecholamines (epinephrine, norepinephrine) from chromaffin cells; regulated by preganglionic sympathetic fibers (acetylcholine).","Catecolaminas; nervos simpáticos."],["13mq0mana","What is the embryologic origin of the adrenal medulla's chromaffin cells?","Neural crest.","Crista neural."],["zb7szjpfs","What is the most common adrenal medulla tumor in adults?","Pheochromocytoma (episodic hypertension).","Feocromocitoma."],["104wh3rfu","What is the most common adrenal medulla tumor in children?","Neuroblastoma (often normotensive).","Neuroblastoma."],["ufcgbqn41","What is the arterial supply of the adrenal glands?","Superior suprarenal (from inferior phrenic), middle suprarenal (from aorta), inferior suprarenal (from renal artery).","Três artérias suprarrenais."],["14euisew5","How do the adrenal veins drain?","Left adrenal vein to left renal vein; right adrenal vein directly to IVC.","Esquerda para a renal; direita para a cava."],["1yd452g1f","What are the two parts of the pituitary gland?","Anterior pituitary (adenohypophysis) and posterior pituitary (neurohypophysis).","Adeno e neuro-hipófise."],["iiftuz15b","What hormones are secreted by the anterior pituitary?","FSH, LH, ACTH, TSH, prolactin, GH, and melanotropin (MSH). Mnemonic: FLAT PiG.","FSH, LH, ACTH, TSH, prolactina, GH."],["16zpnih1o","Which anterior pituitary cells are acidophils vs basophils?","Acidophils: GH, prolactin. Basophils: FSH, LH, ACTH, TSH (B-FLAT).","Acidófilas: GH e prolactina."],["gt8hwc13m","Which hormones share an alpha subunit?","TSH, LH, FSH, and hCG; the beta subunit determines specificity.","TSH, LH, FSH e hCG."],["d7but0uo1","What is the precursor of ACTH and MSH?","Proopiomelanocortin (POMC), which also yields beta-endorphin.","POMC."],["9emun31er","What hormones are released from the posterior pituitary?","Vasopressin (ADH) and oxytocin, made in hypothalamus (supraoptic and paraventricular nuclei) and transported via neurophysins.","ADH e ocitocina."],["1ulf1gkp4","How does the anterior pituitary receive hypothalamic hormones?","Through the hypophyseal portal system.","Sistema porta hipofisário."],["3nj2lx16r","What is the blood supply concern of the pituitary during pregnancy?","The pituitary enlarges without proportional increase in blood supply; postpartum hemorrhage can cause ischemic necrosis (Sheehan syndrome).","Risco de necrose de Sheehan."],["5i2f2t10y","What structure lies directly above the pituitary in the sella turcica?","Optic chiasm.","Quiasma óptico."],["1lhca5n1s","What visual deficit does a pituitary adenoma cause?","Bitemporal hemianopia (compression of the optic chiasm).","Hemianopsia bitemporal."],["en22cvhtc","Which cranial nerves pass through the cavernous sinus lateral to the pituitary?","CN III, IV, V1, V2, VI (and the internal carotid artery).","III, IV, V1, V2 e VI."],["1s7r3o5v6","Where is the thyroid gland located?","Anterior neck, below the cricoid cartilage, with two lobes connected by the isthmus at the level of tracheal rings 2-4.","Pescoço, sobre os anéis traqueais."],["1lgd4nlav","What is the arterial supply of the thyroid?","Superior thyroid artery (from external carotid) and inferior thyroid artery (from thyrocervical trunk of subclavian).","Artérias tireoidianas superior e inferior."],["lzspyx19f","Which nerve runs with the superior thyroid artery and is at risk in thyroidectomy?","External branch of the superior laryngeal nerve (innervates cricothyroid; injury causes voice fatigue, loss of high pitch).","Laríngeo superior externo."],["1qp1zam1i","Which nerve runs with the inferior thyroid artery and is at risk in thyroidectomy?","Recurrent laryngeal nerve (injury causes hoarseness).","Laríngeo recorrente."],["82a0tn1yf","What happens with bilateral recurrent laryngeal nerve injury?","Airway obstruction due to vocal cord paralysis (aphonia, stridor).","Obstrução da via aérea."],["n7pw5u1xl","Which cells produce thyroid hormone vs calcitonin?","Follicular cells: T3/T4. Parafollicular (C) cells: calcitonin.","Foliculares e células C."],["iz2vfy6a7","What is the role of thyroglobulin?","Protein in the follicular colloid on which T3 and T4 are synthesized and stored.","Base para síntese de T3 e T4."],["lcfuq01rq","Where are the parathyroid glands located?","Usually four glands on the posterior surface of the thyroid.","Atrás da tireoide."],["d5xhxf38p","Which cells of the parathyroid produce PTH?","Chief cells.","Células principais."],["1rjma15kz","What is the risk to the parathyroids during thyroidectomy?","Accidental removal or devascularization causing hypocalcemia (tingling, tetany).","Hipocalcemia."],["12tp2akmv","What cells are in the endocrine pancreas (islets of Langerhans)?","Alpha cells (glucagon), beta cells (insulin), delta cells (somatostatin), PP cells (pancreatic polypeptide).","Alfa, beta, delta e PP."],["rh902c17q","Where are beta and alpha cells located in the islet?","Beta cells central, alpha and delta cells peripheral. Insulin inside.","Beta no centro."],["1cmv2nwge","What is the embryologic origin of islet cells?","Pancreatic buds of foregut endoderm.","Endoderma."],["1tqmobngu","What fraction of pancreatic tissue is endocrine?","About 1-2% (islets of Langerhans).","Cerca de 1-2%."],["1jtqs3a1k","Where are the islets most concentrated in the pancreas?","Tail of the pancreas.","Na cauda."],["550wse12v","What is the pineal gland and what does it secrete?","Small gland in the epithalamus that secretes melatonin, regulating circadian rhythm.","Melatonina."],["1btbzdjo5","What is the tumor of the pineal gland that causes Parinaud syndrome?","Pinealoma (germinoma), compressing the dorsal midbrain (vertical gaze palsy).","Pinealoma."],["9d5cgpvu2","What hormones does the placenta make?","hCG, human placental lactogen, estrogen (estriol), progesterone.","hCG, hPL, estrogênio, progesterona."],["cmo7651p7","What is the main endocrine function of the kidney?","Erythropoietin, calcitriol (1-alpha-hydroxylase), renin.","EPO, calcitriol e renina."],["w65uomygg","What does the heart secrete as an endocrine organ?","ANP (atria) and BNP (ventricles).","ANP e BNP."],["db5o741ga","What do enteroendocrine cells produce?","Gastrin (G cells), CCK (I cells), secretin (S cells), GIP (K cells), motilin (M cells), somatostatin (D cells), serotonin (enterochromaffin cells).","Hormônios gastrointestinais."],["1mqq80zz4","What hormone does adipose tissue produce?","Leptin (and adiponectin, resistin).","Leptina."],["99hp0i15o","What is the role of the hypothalamus in endocrine regulation?","Produces releasing/inhibiting hormones (CRH, TRH, GnRH, GHRH, somatostatin, dopamine) and ADH/oxytocin.","Hormônios de liberação."],["cg74h11hp","What is the stalk effect?","Compression of the pituitary stalk reduces dopamine delivery, causing mild hyperprolactinemia.","Compressão eleva a prolactina."],["1qq7kiju4","What is the most common cause of pituitary stalk lesion in children?","Craniopharyngioma.","Craniofaringioma."],["p17xc4158","Which vertebral level are the adrenal glands at?","Approximately T11-T12, on the superior poles of the kidneys.","T11-T12."],["13f0ra4to","Which artery does the right adrenal vein drain directly into, making adrenal vein sampling difficult?","The right adrenal vein is short and drains directly into the IVC, making it hard to cannulate.","Veia cava inferior."],["6j6x8f3vy","What lymph nodes drain the thyroid?","Pretracheal, paratracheal, deep cervical nodes.","Linfonodos cervicais e traqueais."],["1pprjix18","What is a thyroid nodule's best initial imaging test?","Ultrasound (after checking TSH).","Ultrassom."]]},{"name":"Pathology (Part 1)","cards":[["2bpfzyh5s","Signs and symptoms of hyperthyroidism?","Heat intolerance, weight loss with increased appetite, tachycardia, palpitations, arrhythmia (AF), tremor, anxiety, insomnia, diarrhea, warm moist skin, fine hair, hyperreflexia, oligomenorrhea, onycholysis.","Calor, perda de peso, taquicardia, tremor."],["1v0jysmdu","Signs and symptoms of hypothyroidism?","Cold intolerance, weight gain, fatigue, constipation, bradycardia, dry skin, coarse hair, myxedema, slowed reflexes (delayed relaxation), menorrhagia, hyperlipidemia, hypercholesterolemia.","Frio, ganho de peso, bradicardia, pele seca."],["1h0bszg1r","Lab findings in primary hyperthyroidism?","Low TSH, high free T4 (and T3).","TSH baixo e T4 livre alto."],["iyvg841t8","Lab findings in primary hypothyroidism?","High TSH, low free T4.","TSH alto e T4 livre baixo."],["610ymowxk","Lab findings in central (secondary) hypothyroidism?","Low or inappropriately normal TSH with low free T4.","TSH baixo ou normal com T4 baixo."],["8k0x8a1l0","What causes Graves disease?","Autoantibodies (IgG) that stimulate the TSH receptor (thyroid-stimulating immunoglobulins): type II hypersensitivity.","Anticorpos estimulam o receptor de TSH."],["16ii1b3kg","Unique features of Graves disease?","Diffuse goiter, ophthalmopathy (proptosis, extraocular muscle swelling), pretibial myxedema.","Bócio, oftalmopatia, mixedema pré-tibial."],["z25a19414","Why does Graves ophthalmopathy occur?","TSH receptors on retro-orbital fibroblasts and adipocytes are stimulated, increasing glycosaminoglycan production and inflammation.","Fibroblastos da órbita estimulados."],["1l62u86kz","Radioactive iodine uptake in Graves disease?","Diffusely increased.","Captação difusa aumentada."],["yzfmp3844","What is toxic multinodular goiter?","Focal patches of hyperfunctioning follicular cells independent of TSH (TSH receptor activating mutations); patchy uptake on scan.","Nódulos autônomos."],["116xhovez","What is a toxic adenoma?","Single hyperfunctioning nodule (hot nodule) with suppression of the rest of the gland.","Nódulo quente único."],["ioxnmw1ep","What is thyroid storm?","Uncommon but serious hyperthyroid complication triggered by stress (surgery, infection, childbirth): fever, agitation, delirium, tachyarrhythmia, vomiting, diarrhea.","Crise tireotóxica grave."],["37jf9x8sd","Treatment of thyroid storm?","Beta-blockers (propranolol), PTU or methimazole, glucocorticoids, iodine (after thionamide), treat precipitant. The 4 Ps: beta-blockers (propranolol), propylthiouracil, prednisolone, potassium iodide.","Betabloqueador, PTU, corticoide, iodo."],["12d778axs","What is Hashimoto thyroiditis?","Most common cause of hypothyroidism in iodine-sufficient regions; autoimmune with anti-TPO and antithyroglobulin antibodies; associated with HLA-DR3 and DR5.","Tireoidite autoimune; anti-TPO."],["95fywn5vr","Histology of Hashimoto thyroiditis?","Hürthle cells, lymphoid aggregates with germinal centers.","Células de Hürthle e folículos linfoides."],["1763o5n1m","What malignancy risk is increased in Hashimoto thyroiditis?","Primary thyroid lymphoma (marginal zone B-cell or diffuse large B-cell lymphoma).","Linfoma de tireoide."],["xkksbxyce","What is the typical course of Hashimoto thyroiditis?","May be hyperthyroid early (hashitoxicosis) and then becomes hypothyroid; painless goiter.","Pode começar com hipertireoidismo."],["cmtcw41bu","What is subacute granulomatous (de Quervain) thyroiditis?","Self-limited thyroiditis often after a viral infection: painful tender thyroid, high ESR, transient hyperthyroidism then hypothyroidism.","Tireoidite dolorosa pós-viral."],["1wg99o7z6","Histology of de Quervain thyroiditis?","Granulomatous inflammation with giant cells.","Granulomas com células gigantes."],["7pyt7yzqh","Radioactive iodine uptake in de Quervain thyroiditis?","Decreased (damaged follicles release preformed hormone).","Captação baixa."],["133dmohxq","What is postpartum (painless) thyroiditis?","Self-limited lymphocytic thyroiditis within a year after delivery; transient hyperthyroidism, then hypothyroidism; painless; anti-TPO positive.","Tireoidite indolor pós-parto."],["mqomej1cw","What is Riedel thyroiditis?","Thyroid replaced by fibrous tissue extending to local structures (rock-hard, fixed, painless goiter); may be IgG4-related; mimics anaplastic carcinoma.","Tireoide endurecida por fibrose."],["1v8bdntk6","What is congenital hypothyroidism (cretinism)?","Hypothyroidism in newborn due to thyroid dysgenesis (most common in US), dyshormonogenesis, or iodine deficiency.","Hipotireoidismo congênito."],["1dr2dye1g","Features of congenital hypothyroidism?","Pot-bellied, pale, puffy-faced child with protruding umbilicus, protuberant tongue, poor brain development (6 Ps: pot-bellied, pale, puffy face, protruding umbilicus, protuberant tongue, poor brain development).","Barriga grande, língua grande, atraso."],["fqw5k211w","Why is congenital hypothyroidism screened for?","Untreated, it causes irreversible intellectual disability; early levothyroxine prevents it.","Previne deficiência intelectual."],["1mwwdcy15","What is the most common cause of hypothyroidism worldwide?","Iodine deficiency.","Falta de iodo."],["1c9g5xqvq","What is myxedema coma?","Severe decompensated hypothyroidism: altered mental status, hypothermia, bradycardia, hypotension, hypoventilation, hyponatremia; treat with IV levothyroxine and hydrocortisone.","Hipotireoidismo grave descompensado."],["18fhoa01x","What is sick euthyroid syndrome?","Low T3 in severe illness (decreased peripheral conversion) with normal or low TSH; not true thyroid disease.","T3 baixo na doença grave."],["1grt25tc0","Which drugs can cause hypothyroidism?","Amiodarone, lithium, interferon-alpha, checkpoint inhibitors, iodine excess.","Amiodarona, lítio, interferon."],["1knzmq4nm","Which drug can cause both hypothyroidism and hyperthyroidism?","Amiodarone.","Amiodarona."],["nu55py154","What is the most common thyroid cancer?","Papillary carcinoma; excellent prognosis.","Carcinoma papilífero."],["e9bw6fsg3","Histology of papillary thyroid carcinoma?","Empty-appearing nuclei with central clearing (Orphan Annie eyes), psammoma bodies, nuclear grooves.","Núcleos em olho de órfã Annie."],["1g6s94wel","Risk factors and mutations for papillary carcinoma?","Childhood irradiation; RET/PTC rearrangements and BRAF mutations.","Radiação; RET e BRAF."],["1qo4n031s","How does papillary carcinoma spread?","Lymphatic spread (cervical lymph nodes).","Via linfática."],["1l8fhwfme","Features of follicular thyroid carcinoma?","Good prognosis; invades thyroid capsule and vasculature (distinguishes it from follicular adenoma); uniform follicles; hematogenous spread; RAS mutations and PAX8-PPAR-gamma translocations.","Invade cápsula e vasos."],["1el39sy14","Why can't FNA distinguish follicular adenoma from carcinoma?","Diagnosis requires assessing capsular or vascular invasion on surgical histology.","Precisa ver a cápsula."],["1h65tr9bo","Features of medullary thyroid carcinoma?","From parafollicular C cells; produces calcitonin; sheets of polygonal cells in amyloid stroma (calcitonin deposits); associated with MEN2A and MEN2B (RET mutations).","Células C; calcitonina; NEM 2."],["1vyk3uyt8","Features of anaplastic (undifferentiated) thyroid carcinoma?","Older patients; invades local structures causing dysphagia or respiratory compromise; very poor prognosis; TP53 mutations.","Idosos; invasivo; prognóstico ruim."],["1lzx1fh16","Which thyroid nodule features suggest malignancy?","Cold nodule on scan, solid, hypoechoic, microcalcifications, irregular margins, taller than wide, growth, history of radiation.","Nódulo frio, sólido, microcalcificações."],["kcblemhl6","Most common complications of thyroidectomy?","Hoarseness (recurrent laryngeal nerve), hypocalcemia (parathyroid removal), transection of superior laryngeal nerve's external branch.","Rouquidão e hipocalcemia."],["r72rww1sp","What is primary hyperparathyroidism?","Excess PTH usually from a parathyroid adenoma (most common) or hyperplasia; hypercalcemia, hypophosphatemia, hypercalciuria.","PTH alto por adenoma."],["gqzp3u1e5","Symptoms of hypercalcemia?","Stones (renal), bones (pain, osteitis fibrosa cystica), groans (abdominal pain, constipation, peptic ulcer, pancreatitis), thrones (polyuria), psychiatric overtones (depression, fatigue, confusion).","Cálculos, ossos, dor abdominal, poliúria."],["2u9tgcrfx","What is osteitis fibrosa cystica?","Cystic bone spaces filled with brown fibrous tissue (brown tumors from osteoclast activity and hemorrhage) due to hyperparathyroidism; bone pain, subperiosteal resorption.","Lesões ósseas císticas."],["ikayw61dt","What is secondary hyperparathyroidism?","Increased PTH in response to hypocalcemia, typically from chronic kidney disease (decreased phosphate excretion, decreased calcitriol) or vitamin D deficiency.","PTH alto por cálcio baixo."],["1q3smnm11","Lab findings in secondary hyperparathyroidism from CKD?","Low or normal Ca2+, high phosphate, high PTH, high alkaline phosphatase.","Fósforo alto e PTH alto."],["vrh1222xe","What is renal osteodystrophy?","Renal disease leading to bone lesions due to secondary hyperparathyroidism, hyperphosphatemia, and low vitamin D.","Doença óssea da doença renal."],["g7mfig1rn","What is tertiary hyperparathyroidism?","Refractory (autonomous) hyperparathyroidism after long-standing secondary hyperparathyroidism (e.g., CKD); very high PTH with high Ca2+.","PTH autônomo."],["179hsd9ez","What is familial hypocalciuric hypercalcemia?","Autosomal dominant inactivating mutation of the calcium-sensing receptor: mild hypercalcemia, normal or high PTH, low urinary calcium; benign.","Cálcio alto com cálcio urinário baixo."],["1ub30ax17","What is the most common cause of hypercalcemia in hospitalized patients?","Malignancy (PTHrP from squamous cell carcinomas, renal cell carcinoma; bone metastasis; calcitriol from lymphoma).","Câncer."],["4btvcz1ic","Lab findings in humoral hypercalcemia of malignancy?","High Ca2+, low PTH, high PTHrP.","PTHrP alto e PTH baixo."],["tkdw0f1b5","Causes of hypoparathyroidism?","Accidental surgical excision (thyroidectomy), autoimmune destruction, DiGeorge syndrome, autoimmune polyglandular syndrome type 1.","Cirurgia, autoimune, DiGeorge."],["w3vlpsqxr","Signs of hypocalcemia?","Tetany, Chvostek sign (tapping facial nerve causes facial muscle contraction), Trousseau sign (BP cuff causes carpal spasm), QT prolongation, seizures, perioral numbness.","Tetania, Chvostek, Trousseau."],["8q2qok1qe","What is pseudohypoparathyroidism type 1A?","Autosomal dominant end-organ resistance to PTH from GNAS mutation (maternal transmission); hypocalcemia, high PTH; Albright hereditary osteodystrophy.","Resistência ao PTH."],["pf5hhy1sb","Features of Albright hereditary osteodystrophy?","Shortened 4th and 5th digits, short stature, round face, obesity, subcutaneous calcifications, developmental delay.","Dedos curtos e baixa estatura."],["1f3bh7o1r","What is pseudopseudohypoparathyroidism?","Albright hereditary osteodystrophy phenotype with normal PTH and calcium (paternal GNAS mutation).","Fenótipo sem alteração laboratorial."],["1b6pt6x1t","What is a pituitary adenoma?","Most commonly a prolactinoma (benign); can be functional (hormone producing) or nonfunctional.","Tumor benigno da hipófise."],["f5id9etbw","Symptoms of a nonfunctional pituitary adenoma?","Mass effect: bitemporal hemianopia, headache; hypopituitarism.","Efeito de massa."],["m0rrxu1k0","Symptoms of prolactinoma?","Women: galactorrhea, amenorrhea, infertility, low libido. Men: low libido, infertility, gynecomastia, galactorrhea (less common).","Galactorreia e amenorreia."],["prtzt01j4","Treatment of prolactinoma?","Dopamine agonists (cabergoline, bromocriptine); transsphenoidal surgery if refractory.","Cabergolina."],["y4ql461rt","What causes acromegaly?","Excess GH in adults, usually from a pituitary adenoma.","GH em excesso no adulto."],["17zd7aonb","Features of acromegaly?","Large tongue with deep furrows, frontal bossing, coarse facial features, enlarged hands and feet (increased shoe/ring size), diaphoresis, impaired glucose tolerance, hypertension, LVH, cardiomyopathy (main cause of death).","Mãos, pés e mandíbula aumentados."],["a6s2bw1vv","What does excess GH cause in children?","Gigantism (increased linear growth before epiphyseal closure).","Gigantismo."],["kdpr6c16g","Diagnosis of acromegaly?","Elevated serum IGF-1; failure to suppress GH after oral glucose tolerance test; pituitary MRI.","IGF-1 e teste de glicose."],["1r4fn8zkp","Treatment of acromegaly?","Transsphenoidal resection; if not curative, somatostatin analogs (octreotide), GH receptor antagonist (pegvisomant), dopamine agonists.","Cirurgia e octreotida."],["1hqnoiu1o","What is central diabetes insipidus?","Deficiency of ADH production: idiopathic, tumors, trauma, surgery, histiocytosis X.","Falta de ADH."],["17pyzcdx9","What is nephrogenic diabetes insipidus?","Renal resistance to ADH: hereditary (ADH receptor mutation), lithium, demeclocycline, hypercalcemia, hypokalemia.","Rim não responde ao ADH."],["1kxtjm6fw","Symptoms of diabetes insipidus?","Intense thirst, polyuria, inability to concentrate urine.","Sede e poliúria."],["qs0akr1w9","Lab findings in diabetes insipidus?","Urine specific gravity <1.006, urine osmolality <300, serum osmolality >290, hypernatremia (if water intake inadequate).","Urina diluída e sódio alto."],["173zerlz3","How is central DI distinguished from nephrogenic DI?","Water deprivation test then desmopressin: central DI urine osmolality increases >50% after desmopressin; nephrogenic does not.","Teste com desmopressina."],["1ewtpiz1d","Treatment of central diabetes insipidus?","Desmopressin; adequate fluid intake.","Desmopressina."],["gh1180yri","Treatment of nephrogenic diabetes insipidus?","Thiazide diuretics, indomethacin, amiloride (for lithium-induced), low-salt diet, hydration.","Tiazídicos e amilorida."],["mb83h2hsq","What is SIADH?","Excess free water retention due to excessive ADH: euvolemic hyponatremia with continued urinary Na+ excretion, urine osmolality > serum osmolality.","Excesso de ADH; hiponatremia."],["w8tto61ih","Causes of SIADH?","Ectopic ADH (small cell lung cancer), CNS disorders/head trauma, pulmonary disease, drugs (SSRIs, carbamazepine, cyclophosphamide, vincristine).","Câncer de pequenas células e drogas."],["15kxs00lf","Treatment of SIADH?","Fluid restriction (first line), salt tablets, IV hypertonic saline (if severe), conivaptan, tolvaptan, demeclocycline.","Restrição hídrica."],["v13e1v1ih","What happens if hyponatremia is corrected too rapidly?","Osmotic demyelination syndrome (central pontine myelinolysis).","Mielinólise pontina."],["871kjf1rv","What happens if hypernatremia is corrected too rapidly?","Cerebral edema and herniation.","Edema cerebral."],["n3ohfy1bb","Causes of hypopituitarism?","Nonsecreting pituitary adenoma, craniopharyngioma, Sheehan syndrome, empty sella syndrome, pituitary apoplexy, brain injury, radiation.","Tumores, Sheehan, apoplexia."],["18n7a4jq5","What is Sheehan syndrome?","Ischemic infarct of the pituitary after severe postpartum hemorrhage: failure to lactate, absent menstruation, cold intolerance.","Necrose hipofisária pós-parto."],["170h683q7","What is pituitary apoplexy?","Sudden hemorrhage of the pituitary gland, often in the presence of an adenoma: sudden severe headache, visual impairment (bitemporal hemianopia, diplopia from CN III palsy), hypopituitarism.","Hemorragia da hipófise."],["106y9yh13","Why is pituitary apoplexy an emergency?","Acute adrenal insufficiency can cause hypotension and death; requires steroids.","Insuficiência adrenal aguda."],["1l7j60tf6","What is empty sella syndrome?","Atrophy or compression of the pituitary, often idiopathic or from idiopathic intracranial hypertension; usually asymptomatic.","Sela vazia."],["g6or6q13g","What is a craniopharyngioma?","Benign childhood tumor from Rathke pouch remnants: bitemporal hemianopia, calcified cystic mass with motor oil fluid, cholesterol crystals; may cause hypopituitarism and diabetes insipidus.","Tumor da bolsa de Rathke."],["dmarep1k3","What is Laron syndrome?","Defective GH receptor: high GH, low IGF-1, short stature, small head, saddle nose.","Resistência ao GH."],["1p5dt821x","What is the main laboratory distinction between hypothalamic and pituitary hypothyroidism?","TRH stimulation test (historically): pituitary failure shows no TSH rise; hypothalamic shows delayed TSH rise.","Teste com TRH."],["q2pysr1xh","Why does primary hypothyroidism cause pituitary enlargement?","Loss of negative feedback causes thyrotroph hyperplasia (high TRH).","Hiperplasia de tireotrofos."],["1iw6tyn1m","What is the main cause of goiter worldwide?","Iodine deficiency.","Falta de iodo."],["9r5818cdk","What is a euthyroid goiter?","Enlarged thyroid with normal function (e.g., simple multinodular goiter).","Bócio com função normal."],["1cmbogd1u","What is subclinical hypothyroidism?","High TSH with normal free T4; treat in some cases (TSH >10, pregnancy, symptoms).","TSH alto com T4 normal."],["1hhmex2y2","What is the most common cause of hypothyroidism after radioactive iodine?","Radioactive iodine ablation (expected outcome; monitor and replace with levothyroxine).","Iodo radioativo."],["1dnrciey2","How does thyroid disease affect lipids?","Hypothyroidism increases LDL cholesterol; hyperthyroidism decreases it.","Hipotireoidismo eleva LDL."],["1ftmki6le","How does thyroid disease affect the heart?","Hyperthyroidism: tachycardia, AF, high-output failure. Hypothyroidism: bradycardia, pericardial effusion, diastolic hypertension.","Taquicardia ou bradicardia."],["1flzl8p7h","What is apathetic hyperthyroidism?","Hyperthyroidism in elderly patients presenting with depression, weakness, weight loss, AF rather than classic hyperadrenergic signs.","Hipertireoidismo apático no idoso."],["1w5lihgvh","What is factitious thyrotoxicosis and how is it diagnosed?","Exogenous thyroid hormone use: low TSH, high T4, low thyroglobulin, low radioactive iodine uptake.","Tireoglobulina baixa."],["p5aezwyp5","What is struma ovarii?","Ovarian teratoma containing functional thyroid tissue that can cause hyperthyroidism.","Teratoma com tireoide."],["15tsk591q","Why does hyperthyroidism cause osteoporosis?","Increased bone turnover (thyroid hormone stimulates osteoclasts).","Estimula osteoclastos."],["17qof871c","What is the effect of hyperthyroidism on glucose metabolism?","Increased glycogenolysis and gluconeogenesis; may worsen diabetes control.","Piora o controle glicêmico."],["ticg4ihlx","What lab finding distinguishes Graves disease from painless thyroiditis?","Radioactive iodine uptake: high in Graves, low in thyroiditis; TSH receptor antibodies positive in Graves.","Captação de iodo."],["zqs8k51jq","What thyroid disease is associated with HLA-B8 and HLA-DR3?","Graves disease.","Graves."],["17te9zy1c","What is the role of anti-TPO antibodies?","Markers of autoimmune thyroiditis (Hashimoto, postpartum thyroiditis); also present in some Graves patients.","Marca tireoidite autoimune."],["8oexms1p8","What causes hypocalcemia after parathyroidectomy for severe hyperparathyroidism?","Hungry bone syndrome (rapid bone uptake of calcium).","Síndrome do osso faminto."],["saqgtj1db","What is the most common cause of primary hyperparathyroidism in MEN1 and MEN2A?","Parathyroid hyperplasia.","Hiperplasia."],["zt0n03acl","What is a parathyroid carcinoma's typical presentation?","Very high calcium and PTH, palpable neck mass; rare.","Cálcio e PTH muito altos."],["19txtt04c","Which imaging localizes parathyroid adenomas?","Technetium-99m sestamibi scan and neck ultrasound.","Sestamibi e ultrassom."],["b3fmj91sv","What does high PTH with low calcium and high phosphate indicate?","Secondary hyperparathyroidism from CKD (or pseudohypoparathyroidism).","Hiperparatireoidismo secundário."],["1f8lm0684","What does low PTH with low calcium indicate?","Hypoparathyroidism (or severe hypomagnesemia).","Hipoparatireoidismo."],["156kdlor5","What does low PTH with high calcium indicate?","PTH-independent hypercalcemia: malignancy (PTHrP), vitamin D toxicity, granulomatous disease, milk-alkali syndrome, immobilization.","Causas sem PTH."],["eth86r891","What is milk-alkali syndrome?","Excess calcium and absorbable alkali intake (e.g., calcium carbonate antacids) causing hypercalcemia, metabolic alkalosis, and AKI.","Excesso de cálcio e antiácido."],["1wbvjbs13","Acute treatment of severe hypercalcemia?","IV normal saline, calcitonin, bisphosphonates (zoledronic acid); denosumab if refractory; dialysis if severe renal failure.","Soro, calcitonina, bisfosfonato."],["1hwbl0s1c","Treatment of acute symptomatic hypocalcemia?","IV calcium gluconate.","Gluconato de cálcio venoso."]]},{"name":"Pathology (Part 2)","cards":[["1n3ecy17h","What is Cushing syndrome?","Increased cortisol from any cause.","Excesso de cortisol."],["x6f2maiif","Most common cause of Cushing syndrome?","Exogenous glucocorticoids (low ACTH, bilateral adrenal atrophy).","Corticoide exógeno."],["k8k1431ar","Clinical features of Cushing syndrome?","Hypertension, weight gain, moon facies, abdominal striae, truncal obesity, buffalo hump, skin changes (thinning), osteoporosis, hyperglycemia, amenorrhea, immunosuppression. CUSHINGOID.","Obesidade central, estrias, hipertensão."],["1qhudsb10","What is Cushing disease?","ACTH-secreting pituitary adenoma (usually microadenoma); increased ACTH with bilateral adrenal hyperplasia.","Adenoma hipofisário secretor de ACTH."],["1r650zx1n","What is ectopic ACTH secretion?","Nonpituitary tumors secrete ACTH (small cell lung cancer, bronchial carcinoid); very high ACTH, often hypokalemia and hyperpigmentation.","Tumor fora da hipófise produz ACTH."],["quig8f9mo","What causes ACTH-independent Cushing syndrome?","Adrenal adenoma, carcinoma, or nodular adrenal hyperplasia: low ACTH, atrophy of the uninvolved adrenal.","Tumor adrenal com ACTH baixo."],["1p5px7412","Screening tests for Cushing syndrome?","24-hour urine free cortisol, late-night salivary cortisol, low-dose (1 mg) dexamethasone suppression test.","Cortisol urinário, salivar e dexametasona."],["1aw254g1e","How is ACTH-dependent Cushing localized?","High-dose dexamethasone suppresses cortisol in Cushing disease (pituitary) but not in ectopic ACTH; CRH stimulation test; inferior petrosal sinus sampling.","Dexametasona em dose alta."],["y2zpt6dd7","What is Nelson syndrome?","Enlargement of a preexisting ACTH-secreting pituitary adenoma after bilateral adrenalectomy for Cushing disease: hyperpigmentation, headaches, bitemporal hemianopia.","Crescimento do adenoma após adrenalectomia."],["i3w5eb1ku","What is primary adrenal insufficiency (Addison disease)?","Inability of the adrenal glands to produce enough glucocorticoids and mineralocorticoids.","Falta de hormônios adrenais."],["ydnkgliqn","Clinical features of primary adrenal insufficiency?","Weakness, fatigue, nausea, weight loss, hypotension, hyponatremia, hyperkalemia, hyperpigmentation (high ACTH/POMC raises MSH), salt craving.","Fraqueza, hipotensão, hiperpigmentação."],["nk3lxkcju","Most common cause of primary adrenal insufficiency in the developed world?","Autoimmune adrenalitis.","Autoimune."],["dcxyll1os","Most common cause of primary adrenal insufficiency in the developing world?","Tuberculosis.","Tuberculose."],["n9lgz3ssz","How does secondary adrenal insufficiency differ from primary?","Decreased ACTH (pituitary): no hyperpigmentation, no hyperkalemia (aldosterone preserved via RAAS).","Sem hiperpigmentação nem hipercalemia."],["1fz2hfpvy","What is the most common cause of tertiary adrenal insufficiency?","Abrupt cessation of chronic exogenous glucocorticoids (suppressed CRH/ACTH).","Suspensão de corticoide."],["siqcwfm8k","What is acute adrenal insufficiency (adrenal crisis)?","Sudden adrenal failure (stress, infection, steroid withdrawal): acute abdomen, nausea, vomiting, altered mental status, shock; treat with IV hydrocortisone and fluids.","Choque e dor abdominal."],["chkqd383g","What is Waterhouse-Friderichsen syndrome?","Bilateral adrenal hemorrhage in sepsis (usually Neisseria meningitidis) causing acute adrenal insufficiency and DIC.","Hemorragia adrenal por meningococo."],["w0ckjy1li","What is autoimmune polyglandular syndrome type 1?","AIRE mutation: chronic mucocutaneous candidiasis, hypoparathyroidism, adrenal insufficiency.","Candidíase, hipoparatireoidismo, Addison."],["w0ckml1li","What is autoimmune polyglandular syndrome type 2?","Adrenal insufficiency with autoimmune thyroid disease and/or type 1 diabetes (Schmidt syndrome).","Addison com tireoide e diabetes."],["14otglk1c","What is primary hyperaldosteronism (Conn syndrome)?","Excess aldosterone from adrenal adenoma or bilateral adrenal hyperplasia: hypertension, hypokalemia (or normal K+), metabolic alkalosis, low renin.","Hipertensão, hipocalemia, renina baixa."],["5sbe581j3","Why is there no edema in primary hyperaldosteronism?","Aldosterone escape (natriuresis via ANP and pressure natriuresis).","Escape da aldosterona."],["15etkginc","How is primary hyperaldosteronism diagnosed?","High aldosterone-to-renin ratio, confirmed with saline/salt suppression testing; CT; adrenal vein sampling to lateralize.","Relação aldosterona/renina."],["1ne6wktwu","Treatment of primary hyperaldosteronism?","Adenoma: surgical adrenalectomy. Bilateral hyperplasia: spironolactone or eplerenone.","Cirurgia ou espironolactona."],["cztqo615x","What is secondary hyperaldosteronism?","Increased aldosterone due to high renin: renovascular hypertension, heart failure, cirrhosis, nephrotic syndrome.","Renina alta."],["12zzl2n1k","What is glucocorticoid-remediable aldosteronism?","Autosomal dominant fusion gene causing aldosterone synthesis under ACTH control; early-onset hypertension; treated with glucocorticoids.","Hipertensão tratada com corticoide."],["qt0qp188m","What is pheochromocytoma?","Catecholamine-secreting tumor of chromaffin cells in the adrenal medulla.","Tumor produtor de catecolaminas."],["1n0xd592a","Rule of 10s of pheochromocytoma?","About 10% malignant, bilateral, extra-adrenal (paraganglioma), calcify, kids (outdated but useful; many are hereditary).","Regra dos 10."],["iyms4q1jn","Symptoms of pheochromocytoma?","Episodic hypertension with headache, palpitations, pallor, perspiration (the 5 Ps: pressure, pain, perspiration, palpitations, pallor).","Crises de pressão alta e palpitação."],["1d9rn8uzc","Which syndromes are associated with pheochromocytoma?","MEN2A, MEN2B, von Hippel-Lindau, neurofibromatosis type 1, SDH mutations (paraganglioma syndromes).","NEM 2, VHL, NF1."],["l6eu7v46p","Diagnosis of pheochromocytoma?","Elevated plasma free metanephrines or 24-hour urinary metanephrines and catecholamines.","Metanefrinas."],["suqmsck8q","Treatment of pheochromocytoma?","Irreversible alpha-blocker (phenoxybenzamine) first, then beta-blockers, followed by surgical resection.","Alfa-bloqueio e depois cirurgia."],["oej3xl1sk","Why must alpha-blockade precede beta-blockade in pheochromocytoma?","Beta-blockade first leaves alpha receptors unopposed, worsening hypertensive crisis.","Evitar crise hipertensiva."],["1yn2h2a1b","What is neuroblastoma?","Most common extracranial solid tumor in children (usually <4 years), from neural crest cells; often adrenal medulla.","Tumor infantil da crista neural."],["1bivzwu17","Features of neuroblastoma?","Abdominal distension, firm irregular mass crossing the midline, opsoclonus-myoclonus syndrome, elevated HVA and VMA; Homer-Wright rosettes; N-myc amplification.","Massa que cruza a linha média."],["f7xkn94hi","How is neuroblastoma distinguished from Wilms tumor clinically?","Neuroblastoma crosses midline and has elevated catecholamine metabolites; Wilms tumor usually does not cross midline.","Cruza a linha média."],["wqcr991v5","What is MEN1?","Pituitary tumors (prolactin or GH), parathyroid adenomas/hyperplasia, pancreatic endocrine tumors (gastrinoma, insulinoma, VIPoma, glucagonoma); MEN1 gene (menin). 3 Ps.","Hipófise, paratireoide e pâncreas."],["ep053ze4w","What is MEN2A?","Parathyroid hyperplasia, pheochromocytoma, medullary thyroid carcinoma; RET gene. 2 Ps.","Tireoide medular, feo e paratireoide."],["ep058ce4w","What is MEN2B?","Pheochromocytoma, medullary thyroid carcinoma, mucosal neuromas (oral/intestinal), marfanoid habitus; RET gene. 1 P.","Tireoide medular, feo e neuromas."],["1rn91pu1q","What are carcinoid tumors?","Neuroendocrine tumors (often GI tract) that secrete serotonin; most often in small intestine; appendix carcinoids usually benign.","Tumores neuroendócrinos."],["4lxg3te6l","What is carcinoid syndrome?","Flushing, diarrhea, wheezing, right-sided valvular disease (tricuspid regurgitation, pulmonic stenosis) when serotonin bypasses liver metabolism (liver metastases or extraintestinal primary).","Rubor, diarreia, sibilância."],["52qshfbyx","Diagnosis of carcinoid syndrome?","Elevated 24-hour urinary 5-HIAA.","5-HIAA urinário."],["t0rgyc1s4","Treatment of carcinoid syndrome?","Surgical resection; somatostatin analogs (octreotide); telotristat for diarrhea.","Cirurgia e octreotida."],["1qfvz2qy4","Why can carcinoid syndrome cause pellagra?","Tryptophan is diverted to serotonin synthesis, depleting niacin.","Triptofano desviado."],["qipnehrcl","What is a gastrinoma (Zollinger-Ellison syndrome)?","Gastrin-secreting tumor of the duodenum or pancreas: recurrent ulcers in distal duodenum/jejunum, abdominal pain, diarrhea (malabsorption); positive secretin stimulation test.","Úlceras por gastrina."],["10nvui41h","What is an insulinoma?","Tumor of pancreatic beta cells: hypoglycemia with high insulin and high C-peptide; Whipple triad (low glucose, symptoms, relief with glucose).","Hipoglicemia com insulina alta."],["o9pwm51p4","How is insulinoma distinguished from exogenous insulin use?","Insulinoma: high C-peptide. Exogenous insulin: low C-peptide.","Peptídeo C alto."],["14q2cvmbb","What is a glucagonoma?","Alpha-cell tumor: dermatitis (necrolytic migratory erythema), diabetes, DVT, declining weight, depression (5 Ds).","Dermatite e diabetes."],["19j5v7r1q","What is a VIPoma?","Tumor secreting VIP: watery diarrhea, hypokalemia, achlorhydria (WDHA syndrome).","Diarreia aquosa."],["yfxxzq1wu","What is a somatostatinoma?","Delta-cell tumor: diabetes, steatorrhea, gallstones, achlorhydria.","Diabetes e cálculos."],["lei3btsgo","What is type 1 diabetes mellitus?","Autoimmune T-cell mediated destruction of beta cells; absolute insulin deficiency; associated with HLA-DR3 and HLA-DR4; anti-GAD, anti-islet cell, anti-insulin antibodies.","Destruição autoimune das células beta."],["ansh16tq7","What is type 2 diabetes mellitus?","Insulin resistance with progressive beta-cell dysfunction; strong genetic predisposition and obesity; islet amyloid polypeptide deposits.","Resistência à insulina."],["11acvnz16","Diagnostic criteria for diabetes mellitus?","HbA1c ≥6.5%, fasting glucose ≥126 mg/dL, 2-hour OGTT glucose ≥200 mg/dL, or random glucose ≥200 with symptoms.","HbA1c ≥6,5% ou glicemias."],["40u5fk1nl","Acute symptoms of hyperglycemia?","Polyuria, polydipsia, polyphagia, weight loss, blurry vision.","Poliúria, polidipsia, polifagia."],["1tfiq125e","Chronic microvascular complications of diabetes?","Retinopathy, nephropathy (nodular glomerulosclerosis, Kimmelstiel-Wilson nodules), neuropathy.","Retinopatia, nefropatia, neuropatia."],["1yv2q1aat","Chronic macrovascular complications of diabetes?","Coronary artery disease, stroke, peripheral artery disease (gangrene).","Coronária, AVC, doença arterial."],["1o4aj5w1f","Mechanism of diabetic complications?","Nonenzymatic glycation (advanced glycation end products), osmotic damage (sorbitol accumulation in nerves, retina, kidneys), oxidative stress.","Glicação e sorbitol."],["1yz0vyb82","What is diabetic ketoacidosis?","Insulin deficiency with increased counterregulatory hormones causing lipolysis and ketogenesis; usually type 1 diabetes, often triggered by infection or missed insulin.","Falta de insulina com cetose."],["duajatsez","Clinical features of DKA?","Kussmaul respirations, nausea, vomiting, abdominal pain, psychosis/delirium, dehydration, fruity breath odor.","Respiração de Kussmaul."],["10c792ifw","Lab findings in DKA?","Hyperglycemia, anion gap metabolic acidosis, ketonemia, hyperkalemia (total body K+ depleted), leukocytosis.","Acidose com ânion gap."],["1p2woc9y9","Treatment of DKA?","IV fluids, IV insulin, potassium replacement (to prevent hypokalemia when insulin shifts K+ into cells), glucose once glucose falls, treat trigger.","Soro, insulina e potássio."],["1g8mcb31g","What is hyperosmolar hyperglycemic state?","Severe hyperglycemia (often >600 mg/dL) with high osmolality and profound dehydration, minimal ketosis; usually type 2 diabetes in elderly; altered mental status.","Glicose muito alta sem cetose."],["pkjl2e1nq","Why does HHS lack significant ketosis?","Some insulin remains, enough to suppress lipolysis and ketogenesis.","Ainda há insulina."],["dn8cqabg1","What is maturity-onset diabetes of the young (MODY)?","Autosomal dominant monogenic diabetes, e.g., glucokinase (MODY2) or HNF1-alpha (MODY3) mutations; mild hyperglycemia in young nonobese patients.","Diabetes monogênico."],["fvs2gm86k","What is gestational diabetes?","Glucose intolerance first recognized in pregnancy due to placental hormones (hPL); increased risk of macrosomia and later type 2 diabetes.","Diabetes na gestação."],["4wsnn31tm","What is the Somogyi effect vs dawn phenomenon?","Somogyi: nocturnal hypoglycemia causes rebound morning hyperglycemia. Dawn phenomenon: early morning hyperglycemia due to GH/cortisol surge without nocturnal hypoglycemia.","Rebote versus aumento matinal."],["10m4t33y0","What is a diabetic foot ulcer's main cause?","Peripheral neuropathy (loss of protective sensation) plus vascular disease.","Neuropatia."],["17g46jl40","What is acanthosis nigricans associated with?","Insulin resistance (obesity, type 2 diabetes, PCOS) and rarely gastric adenocarcinoma.","Resistência à insulina."],["12eohu4fz","What is diabetic gastroparesis?","Autonomic neuropathy causing delayed gastric emptying: early satiety, nausea, vomiting; treat with metoclopramide or erythromycin.","Esvaziamento gástrico lento."],["aisqqzkjf","Which diabetes complication causes painless foot deformity and joint destruction?","Charcot joint (neuropathic arthropathy).","Articulação de Charcot."],["1t6qhutt0","What is hypoglycemia unawareness?","Loss of adrenergic warning symptoms of hypoglycemia, especially with repeated episodes or beta-blockers, in long-standing diabetes.","Sem sintomas de alerta."],["t8tajt1kt","What is metabolic syndrome?","Abdominal obesity, hypertriglyceridemia, low HDL, hypertension, elevated fasting glucose (3 of 5); increased CVD and diabetes risk.","Obesidade central e dislipidemia."],["ydts3j1u1","What is congenital adrenal hyperplasia's most common form?","21-hydroxylase deficiency.","21-hidroxilase."],["14wg5z2tu","Presentation of classic salt-wasting 21-hydroxylase deficiency?","Newborn with hyponatremia, hyperkalemia, hypotension (salt wasting); ambiguous genitalia in XX infants; detected by newborn screen (high 17-hydroxyprogesterone).","Perda de sal no recém-nascido."],["1z0wns7bz","Presentation of nonclassic 21-hydroxylase deficiency?","Hirsutism, acne, irregular menses in adolescent/young women (mimics PCOS).","Hirsutismo na adolescente."],["57xyp7rk1","Why does CAH cause adrenal hyperplasia?","Low cortisol increases ACTH via loss of negative feedback, stimulating adrenal growth.","ACTH alto."],["1p2vwjhy9","Treatment of CAH?","Glucocorticoids (suppress ACTH) plus mineralocorticoids if salt-wasting.","Corticoide."],["1dd15j110","What is an incidentaloma?","Adrenal mass found incidentally on imaging; evaluate for hormone secretion and malignancy (size >4 cm, imaging features).","Massa adrenal achada por acaso."],["uvq5qb1dm","What is adrenocortical carcinoma?","Rare aggressive tumor, often large (>6 cm), secreting cortisol and androgens; associated with Li-Fraumeni and Beckwith-Wiedemann.","Tumor adrenal agressivo."],["atchqdsd8","What is hyperprolactinemia caused by drugs?","Dopamine antagonists (antipsychotics, metoclopramide), estrogens, TCAs, verapamil, opioids.","Antipsicóticos e metoclopramida."],["1onzlnl1n","What is hypogonadotropic hypogonadism?","Low FSH/LH with low sex steroids: Kallmann syndrome, hyperprolactinemia, anorexia, excess exercise, pituitary disease.","LH e FSH baixos."],["si3cnabn6","What is short stature's most common causes?","Constitutional growth delay and familial short stature.","Constitucional e familiar."],["crbv9k5a7","How do you distinguish constitutional growth delay from familial short stature?","Constitutional delay: delayed bone age, delayed puberty, normal final height. Familial short stature: normal bone age, short parents.","Idade óssea atrasada ou normal."],["p33knd1bt","What is precocious puberty's central cause?","Early activation of the hypothalamic-pituitary-gonadal axis (high LH/FSH), often idiopathic in girls; CNS lesions (hamartoma) more likely in boys.","Ativação precoce do eixo."],["pas8fn1d5","What is peripheral precocious puberty?","Sex steroids independent of GnRH (low LH/FSH): CAH, tumors, McCune-Albright, exogenous hormones.","Esteroides independentes do GnRH."],["1csubjf1e","What is the most common thyroid finding in Down syndrome?","Hypothyroidism.","Hipotireoidismo."],["1ax6ybios","What is euthyroid hyperthyroxinemia?","Elevated total T4 with normal free T4 and TSH (e.g., increased TBG); patient is euthyroid.","TBG alta."],["1vdw2yo1i","What is thyroid hormone resistance?","Mutation in the thyroid hormone receptor (beta): high T4/T3 with normal or high TSH; variable symptoms.","Receptor mutado."],["3bqbwc19r","What is TSH-secreting pituitary adenoma?","Rare: high T4/T3 with inappropriately normal or high TSH; goiter and hyperthyroid symptoms.","T4 alto com TSH alto."],["ed581e81p","What is pituitary gigantism associated with?","GH excess in childhood: McCune-Albright syndrome, MEN1, Carney complex.","McCune-Albright e NEM1."],["lic694z7n","What is Carney complex?","Spotty skin pigmentation, myxomas (cardiac), endocrine overactivity (Cushing via primary pigmented nodular adrenocortical disease, acromegaly); PRKAR1A mutation.","Manchas, mixomas e Cushing."],["p83gbnvd2","What is the effect of glucocorticoids on the thyroid?","Decrease TSH secretion and peripheral T4 to T3 conversion.","Reduzem TSH."],["4h9tdwjh8","What is the effect of hyperthyroidism on calcium?","Mild hypercalcemia from increased bone resorption.","Cálcio levemente alto."],["s3bj5814g","What is the cause of hypokalemia in Cushing syndrome?","Cortisol at high levels stimulates mineralocorticoid receptors (overwhelms 11-beta-HSD2), especially in ectopic ACTH.","Cortisol age como aldosterona."],["1cmcj9deq","What is apparent mineralocorticoid excess?","Deficiency of 11-beta-hydroxysteroid dehydrogenase type 2 (or licorice ingestion), allowing cortisol to activate mineralocorticoid receptors: hypertension, hypokalemia, low renin and low aldosterone.","Deficiência de 11-beta-HSD2."],["18zrdeb13","What is Liddle syndrome?","Gain of function of ENaC in collecting duct: hypertension, hypokalemia, metabolic alkalosis, low renin and low aldosterone; treated with amiloride.","ENaC hiperativo."],["k13896635","What is Bartter syndrome?","Defective NKCC2 in thick ascending limb (like loop diuretic): hypokalemia, metabolic alkalosis, hypercalciuria, normotension, high renin/aldosterone.","Como diurético de alça."],["1gvip8ub3","What is Gitelman syndrome?","Defective NCC in distal convoluted tubule (like thiazide): hypokalemia, metabolic alkalosis, hypomagnesemia, hypocalciuria, normotension.","Como tiazídico."],["1aa1fkm52","What is the classic electrolyte pattern of adrenal insufficiency?","Hyponatremia, hyperkalemia, hypoglycemia, mild metabolic acidosis (primary).","Sódio baixo, potássio alto."],["11zqigqgd","What is the role of hydrocortisone stress dosing?","Patients on chronic steroids or with adrenal insufficiency need increased doses during surgery or illness to prevent adrenal crisis.","Dobrar o corticoide no estresse."],["1sfu0r6kc","What lab finding is typical of hypothyroidism-related myopathy?","Elevated creatine kinase.","CPK alta."],["1iqprfb9j","What is the classic eye finding in hypercalcemia?","Band keratopathy (calcium deposits in cornea).","Ceratopatia em faixa."],["e91kr5vrb","What is the typical ECG finding in hypercalcemia?","Shortened QT interval.","QT curto."],["3dr1dd19b","What is osteomalacia's lab pattern?","Low calcium, low phosphate, high PTH, high alkaline phosphatase, low vitamin D.","Cálcio, fosfato e vitamina D baixos."],["15qbb4nqp","What is the lab pattern in Paget disease of bone?","Normal calcium and phosphate, normal PTH, markedly increased alkaline phosphatase.","FA isolada alta."],["cc3916yh3","What is the lab pattern in osteoporosis?","Normal calcium, phosphate, PTH, alkaline phosphatase.","Tudo normal."],["q2t9om1mn","What is hungry bone syndrome?","Profound hypocalcemia after parathyroidectomy as bone remineralizes.","Hipocalcemia após paratireoidectomia."],["9dhva1cse","What is a thyroglossal duct cyst's risk?","Infection and rarely papillary carcinoma; treated with Sistrunk procedure (including middle hyoid bone).","Infecção e câncer."]]},{"name":"Pharmacology","cards":[["1hzcgpc1k","Which insulins are rapid acting?","Lispro, aspart, glulisine (no LAG); used for postprandial glucose control.","Lispro, asparte, glulisina."],["fkjv77gbm","Which insulin is short acting?","Regular insulin; used IV for DKA, hyperkalemia, and stress hyperglycemia.","Insulina regular."],["10rqlgw15","Which insulin is intermediate acting?","NPH insulin.","NPH."],["qenm3813d","Which insulins are long acting?","Detemir, glargine, degludec; basal glucose control.","Glargina, detemir, degludeca."],["w5xqbznpa","Adverse effects of insulin?","Hypoglycemia, lipodystrophy, weight gain, hypokalemia, rare hypersensitivity.","Hipoglicemia e ganho de peso."],["hxncqjeat","How does insulin treat hyperkalemia?","Shifts K+ into cells by stimulating Na+/K+-ATPase (given with glucose).","Joga potássio para dentro da célula."],["j2uhxh1bc","Mechanism of metformin?","Inhibits hepatic gluconeogenesis and glycerophosphate dehydrogenase; increases insulin sensitivity; activates AMPK; decreases intestinal glucose absorption.","Reduz gliconeogênese hepática."],["1russkm6v","Advantages of metformin?","First-line for type 2 diabetes; causes weight loss (or neutral); does not cause hypoglycemia.","Primeira linha; sem hipoglicemia."],["1xpaw2wjv","Adverse effects of metformin?","GI upset, lactic acidosis (avoid in significant renal insufficiency), vitamin B12 deficiency.","Diarreia, acidose lática, falta de B12."],["11nxaow1e","Mechanism of sulfonylureas?","Close K+ channels in beta-cell membranes, depolarizing cells and increasing insulin release.","Fecham canal de potássio e liberam insulina."],["13sg8hs11","Examples of sulfonylureas?","First generation: chlorpropamide, tolbutamide. Second generation: glipizide, glyburide, glimepiride.","Glipizida, glibenclamida, glimepirida."],["plh9ot10l","Adverse effects of sulfonylureas?","Hypoglycemia (especially in renal insufficiency), weight gain; first generation: disulfiram-like reaction.","Hipoglicemia e ganho de peso."],["6air3e114","Mechanism of meglitinides?","Repaglinide, nateglinide: close K+ channels in beta cells (like sulfonylureas, different binding site); short acting.","Como sulfonilureias, ação curta."],["1mni174r1","Mechanism of thiazolidinediones?","Pioglitazone, rosiglitazone: activate PPAR-gamma, increasing insulin sensitivity and adiponectin.","Ativam PPAR-gama."],["1n186n11o","Adverse effects of thiazolidinediones?","Weight gain, edema, heart failure, increased fracture risk; rosiglitazone may increase MI risk; pioglitazone may increase bladder cancer risk.","Edema, insuficiência cardíaca, fraturas."],["nz6b6wc6w","Contraindication to thiazolidinediones?","Heart failure (NYHA III-IV).","Insuficiência cardíaca."],["1g5dz1xjh","Mechanism of GLP-1 receptor agonists?","Exenatide, liraglutide, semaglutide, dulaglutide: increase glucose-dependent insulin release, decrease glucagon, delay gastric emptying, increase satiety.","Aumentam insulina e saciedade."],["jhc59adyp","Advantages of GLP-1 receptor agonists?","Weight loss and cardiovascular benefit (liraglutide, semaglutide); low hypoglycemia risk alone.","Perda de peso e proteção cardíaca."],["127gamox0","Adverse effects of GLP-1 receptor agonists?","Nausea, vomiting, pancreatitis, possible medullary thyroid carcinoma risk (rodents).","Náusea e pancreatite."],["1lmvnr9a1","Contraindication to GLP-1 receptor agonists?","Personal or family history of medullary thyroid carcinoma or MEN2.","Carcinoma medular de tireoide."],["kjcxytstu","Mechanism of tirzepatide?","Dual GIP and GLP-1 receptor agonist used for type 2 diabetes and obesity.","Agonista duplo GIP e GLP-1."],["wb5kiq1yk","Mechanism of DPP-4 inhibitors?","Sitagliptin, linagliptin, saxagliptin, alogliptin: inhibit degradation of endogenous incretins (GLP-1, GIP).","Aumentam as incretinas."],["pta0f1gty","Adverse effects of DPP-4 inhibitors?","Respiratory and urinary infections, weight neutral, mild hypoglycemia risk; possible pancreatitis.","Infecções respiratórias."],["9bne69djc","Mechanism of SGLT2 inhibitors?","Canagliflozin, dapagliflozin, empagliflozin: block glucose reabsorption in the PCT, causing glucosuria.","Glicose sai na urina."],["1r8o95t1u","Benefits of SGLT2 inhibitors beyond glucose?","Weight loss, decreased BP, reduced heart failure hospitalization, renal protection, decreased cardiovascular mortality.","Protegem coração e rim."],["12gbabwh2","Adverse effects of SGLT2 inhibitors?","Glucosuria, UTIs, vulvovaginal candidiasis, dehydration (orthostatic hypotension), euglycemic DKA, Fournier gangrene (rare).","Infecção urinária e cetoacidose euglicêmica."],["ajzh8d4mc","Mechanism of alpha-glucosidase inhibitors?","Acarbose, miglitol: inhibit intestinal brush-border alpha-glucosidases, delaying carbohydrate absorption and reducing postprandial hyperglycemia.","Atrasam absorção de carboidratos."],["179woc01h","Adverse effects of alpha-glucosidase inhibitors?","GI upset, bloating, flatulence.","Flatulência."],["vihvkh166","Mechanism of pramlintide?","Amylin analog: decreases gastric emptying and glucagon secretion; used in type 1 and 2 diabetes.","Análogo da amilina."],["1kgsat173","Mechanism of thioamides?","Propylthiouracil and methimazole block thyroid peroxidase, inhibiting oxidation of iodide and organification/coupling.","Inibem a peroxidase."],["1jmjjq9fv","What extra action does propylthiouracil have?","Blocks 5'-deiodinase, decreasing peripheral T4 to T3 conversion.","Bloqueia conversão de T4 em T3."],["10b5rru1p","Clinical use of PTU vs methimazole in pregnancy?","PTU in the first trimester (methimazole is teratogenic: aplasia cutis); methimazole in the second and third trimesters (PTU hepatotoxicity).","PTU no 1º trimestre; metimazol depois."],["1tjpqh4rb","Adverse effects of thioamides?","Agranulocytosis, aplastic anemia, skin rash; PTU: severe hepatotoxicity, ANCA vasculitis.","Agranulocitose."],["wrhi5w11i","What should a patient on methimazole do if they develop fever and sore throat?","Stop the drug and check a CBC for agranulocytosis.","Suspender e fazer hemograma."],["1l8j5zmm0","Mechanism and use of levothyroxine?","Synthetic T4; hypothyroidism and myxedema; TSH suppression in thyroid cancer.","T4 sintético."],["33jvos1m9","Adverse effects of levothyroxine excess?","Tachycardia, heat intolerance, tremor, arrhythmias (AF), osteoporosis.","Sintomas de hipertireoidismo."],["161dqusjv","What is liothyronine?","Synthetic T3; occasionally used for myxedema coma or specific situations.","T3 sintético."],["1r226dy8y","Mechanism of radioactive iodine therapy?","I-131 is taken up by thyroid cells and destroys them; used for Graves disease, toxic nodules, thyroid cancer; contraindicated in pregnancy.","Destrói células da tireoide."],["1hy5wgs34","Mechanism of potassium iodide in thyroid storm?","Inhibits thyroid hormone release (Wolff-Chaikoff) and decreases gland vascularity before surgery.","Bloqueia liberação de hormônio."],["1tveqbw1q","Why are beta-blockers used in hyperthyroidism?","Control adrenergic symptoms; propranolol also decreases T4 to T3 conversion.","Controlam sintomas adrenérgicos."],["18r0ram15","Mechanism and use of desmopressin (ADH analog)?","V2 agonist: central diabetes insipidus, von Willebrand disease, hemophilia A (increases factor VIII), sleep enuresis.","Agonista V2."],["18fwc8n1k","Mechanism and use of conivaptan and tolvaptan?","ADH receptor (V2) antagonists; treat SIADH (block water reabsorption).","Bloqueiam o ADH."],["1hjd125o5","Adverse effect of tolvaptan?","Overly rapid correction of hyponatremia (osmotic demyelination), hepatotoxicity.","Correção rápida do sódio."],["1uirlguc5","Mechanism and use of demeclocycline in SIADH?","Tetracycline that causes nephrogenic DI by interfering with ADH action; adverse: photosensitivity, bone and teeth abnormalities.","Causa diabetes insípido."],["4k410cyh7","Mechanism and use of octreotide?","Somatostatin analog: acromegaly, carcinoid syndrome, VIPoma, glucagonoma, esophageal varices.","Análogo da somatostatina."],["8jwoxl1hp","Adverse effects of octreotide?","Nausea, cramps, steatorrhea, cholelithiasis (decreased CCK).","Cálculos biliares."],["6nmyfb132","Mechanism and use of pegvisomant?","GH receptor antagonist; acromegaly.","Bloqueia o receptor de GH."],["1arkbjt11","Mechanism and use of cabergoline and bromocriptine?","Dopamine D2 agonists: prolactinoma, acromegaly (adjunct), Parkinson (bromocriptine).","Agonistas de dopamina."],["1772jqexx","Mechanism and use of oxytocin as a drug?","Induces labor (uterine contractions), stimulates milk letdown, controls postpartum uterine bleeding.","Contrações uterinas."],["ghsqmsn4p","Adverse effects of oxytocin?","Uterine hyperstimulation, water intoxication (hyponatremia, ADH-like effect).","Hiperestimulação e hiponatremia."],["kkmy341iy","Name commonly used glucocorticoids.","Hydrocortisone, prednisone, prednisolone, methylprednisolone, dexamethasone, triamcinolone, fludrocortisone (mainly mineralocorticoid), beclomethasone, budesonide.","Prednisona, dexametasona e outros."],["1bxiy04hj","Mechanism of glucocorticoid anti-inflammatory action?","Bind intracellular receptors altering gene transcription; inhibit NF-kB and phospholipase A2 (decreased prostaglandins, leukotrienes); decrease cytokines.","Inibem NF-kB."],["hvkz401ot","Uses of glucocorticoids?","Addison disease, inflammation, immunosuppression, asthma, CAH, cerebral edema (dexamethasone).","Inflamação e imunossupressão."],["1sgl8ys1v","Adverse effects of chronic glucocorticoid use?","Cushing syndrome, hyperglycemia, osteoporosis, avascular necrosis, cataracts, glaucoma, peptic ulcer, adrenal suppression, immunosuppression, psychosis, myopathy, skin thinning.","Cushing, osteoporose, diabetes."],["1nsc1ja1w","Why must chronic glucocorticoids be tapered?","Abrupt withdrawal after HPA suppression can cause adrenal insufficiency.","Risco de insuficiência adrenal."],["156no1vew","Which glucocorticoid has the greatest mineralocorticoid activity?","Fludrocortisone (used for primary adrenal insufficiency and orthostatic hypotension).","Fludrocortisona."],["rl5831aiy","Which glucocorticoid has essentially no mineralocorticoid effect?","Dexamethasone.","Dexametasona."],["12tj4nt1t","Mechanism and use of cinacalcet?","Sensitizes calcium-sensing receptor in the parathyroid to Ca2+, decreasing PTH; used for secondary hyperparathyroidism in CKD and parathyroid carcinoma.","Reduz PTH."],["10mruzzul","Adverse effect of cinacalcet?","Hypocalcemia.","Hipocalcemia."],["c9cf4i1pk","Mechanism and use of sevelamer?","Nonabsorbable phosphate binder; hyperphosphatemia in CKD.","Quelante de fósforo."],["d949mi1t3","Mechanism and use of calcitriol and paricalcitol?","Active vitamin D analogs; secondary hyperparathyroidism and hypocalcemia in CKD.","Vitamina D ativa."],["1c6adlyfj","Mechanism and use of bisphosphonates?","Alendronate, zoledronic acid: pyrophosphate analogs that bind hydroxyapatite and inhibit osteoclast activity; osteoporosis, hypercalcemia, Paget disease.","Inibem osteoclastos."],["11atyubuc","Adverse effects of bisphosphonates?","Erosive esophagitis (take upright with water), osteonecrosis of the jaw, atypical femoral fractures.","Esofagite e osteonecrose."],["1o0en4w1o","Mechanism of denosumab?","Monoclonal antibody against RANKL, inhibiting osteoclast maturation; osteoporosis and bone metastases.","Anti-RANKL."],["1ja1pmk9j","Mechanism of teriparatide?","Recombinant PTH analog given intermittently (daily injection), increasing osteoblast activity; severe osteoporosis.","PTH intermitente forma osso."],["bqo95u1th","Adverse effect of teriparatide?","Transient hypercalcemia, possible osteosarcoma risk in rodents (avoid in Paget disease or prior radiation).","Hipercalcemia transitória."],["qr2f2913a","Mechanism and use of calcitonin as a drug?","Decreases bone resorption; acute hypercalcemia; rarely osteoporosis.","Reduz reabsorção óssea."],["33u2s013c","Mechanism and use of spironolactone in endocrine disease?","Aldosterone receptor antagonist; primary hyperaldosteronism, hirsutism (antiandrogen effect).","Antagonista da aldosterona."],["1wxmyj117","Adverse effects of spironolactone?","Hyperkalemia, gynecomastia (eplerenone has fewer antiandrogen effects).","Hipercalemia e ginecomastia."],["17x6no59s","Mechanism and use of ketoconazole in Cushing syndrome?","Inhibits steroid synthesis enzymes (cholesterol desmolase, 17,20-lyase) to reduce cortisol.","Inibe síntese de esteroides."],["n5cwiqwt2","Mechanism and use of metyrapone?","Inhibits 11-beta-hydroxylase, decreasing cortisol synthesis; Cushing syndrome treatment and diagnostic testing.","Inibe 11-beta-hidroxilase."],["1pcgmlsan","Mechanism and use of mifepristone in Cushing syndrome?","Glucocorticoid receptor antagonist; hyperglycemia due to Cushing syndrome (also progesterone receptor antagonist).","Bloqueia receptor de glicocorticoide."],["ilez3116h","Mechanism and use of osilodrostat?","Inhibits 11-beta-hydroxylase; Cushing disease.","Inibe 11-beta-hidroxilase."],["1cxbsx01t","Mechanism of phenoxybenzamine in pheochromocytoma?","Irreversible nonselective alpha-blocker used preoperatively.","Alfa-bloqueador irreversível."],["15w9q4h1d","Mechanism of metyrosine?","Inhibits tyrosine hydroxylase, decreasing catecholamine synthesis; adjunct for pheochromocytoma.","Inibe tirosina hidroxilase."],["wx5i8dtod","Mechanism and use of glucagon as a drug?","Increases cAMP: severe hypoglycemia, beta-blocker overdose, and to relax GI tract for imaging.","Hipoglicemia e betabloqueador."],["1uh8nk9fb","Mechanism and use of diazoxide?","Opens K+ channels in beta cells to inhibit insulin release; treats insulinoma and hyperinsulinemic hypoglycemia.","Abre canais de potássio."],["8mj0m61o8","Which drug class increases risk of hypoglycemia unawareness in diabetics?","Nonselective beta-blockers.","Betabloqueadores."],["132iuvv15","Which diabetes medication is contraindicated in patients with eGFR <30?","Metformin.","Metformina."],["p7np5l94o","Which diabetes drugs cause weight gain?","Insulin, sulfonylureas, meglitinides, thiazolidinediones.","Insulina, sulfonilureias, glitazonas."],["pgmkhn95f","Which diabetes drugs cause weight loss?","GLP-1 receptor agonists, SGLT2 inhibitors, metformin (modest).","GLP-1, glifozinas, metformina."]]},{"name":"Physiology","cards":[["1ryk5311s","What stimulates insulin secretion?","Hyperglycemia (glucose via GLUT2), GLP-1, GIP (incretins), amino acids, sulfonylureas, vagal stimulation; inhibited by somatostatin and alpha2 adrenergic.","Glicose, incretinas, aminoácidos."],["6nrlx51c0","How does glucose trigger insulin release from beta cells?","Glucose enters via GLUT2, is metabolized to ATP, ATP closes K+ channels, depolarization opens Ca2+ channels, Ca2+ influx triggers insulin exocytosis.","Glicose fecha canal de potássio e entra cálcio."],["1oxpjmgdw","What are the effects of insulin?","Increases glucose uptake (muscle/adipose), glycogen, lipid, and protein synthesis, Na+ retention, K+ and amino acid uptake; decreases glucagon release and lipolysis.","Captação de glicose e anabolismo."],["101fgvv1s","What is C-peptide used for clinically?","Marker of endogenous insulin; low in exogenous insulin use, high in insulinoma or sulfonylurea use.","Marca insulina própria."],["1flbo9mdi","Which insulin receptor type is it?","Tyrosine kinase receptor (PI3K pathway and RAS/MAPK pathway).","Receptor tirosina quinase."],["1vnxq4tfw","What stimulates glucagon secretion?","Hypoglycemia, amino acids, sympathetic stimulation; inhibited by insulin, hyperglycemia, somatostatin.","Hipoglicemia e aminoácidos."],["1cy7h6w1k","What are the effects of glucagon?","Glycogenolysis, gluconeogenesis, lipolysis, ketone production.","Glicogenólise e gliconeogênese."],["1x7qpu2bf","What is the action of TRH?","Stimulates TSH and prolactin release.","Libera TSH e prolactina."],["1x7tx4tbf","What is the action of CRH?","Stimulates ACTH release; increased in chronic exogenous steroid absence.","Libera ACTH."],["b9uroxm1d","What is the action of GHRH?","Stimulates GH release; analog tesamorelin treats HIV-associated lipodystrophy.","Libera GH."],["6koyxm1wp","What is the action of somatostatin?","Inhibits GH and TSH release (and many GI hormones).","Inibe GH e TSH."],["1b8at6u13","What is the action of dopamine on the pituitary?","Inhibits prolactin release.","Inibe prolactina."],["baeslzm0n","What is the action of GnRH?","Stimulates FSH and LH release; pulsatile secretion stimulates, continuous secretion suppresses.","Pulsátil estimula LH e FSH."],["1ctvv5g1g","What is the action of prolactin?","Stimulates milk production; inhibits ovulation (by inhibiting GnRH) and spermatogenesis.","Produção de leite."],["161cstw1k","What regulates prolactin secretion?","Tonically inhibited by dopamine; stimulated by TRH, estrogen (pregnancy), nipple stimulation.","Dopamina inibe."],["13of8ju1l","Why does hypothyroidism cause hyperprolactinemia?","Increased TRH stimulates prolactin release.","TRH estimula prolactina."],["1i0i0cfaf","What are the effects of growth hormone?","Stimulates linear growth and muscle mass via IGF-1 (somatomedin C) secretion by the liver; increases insulin resistance (diabetogenic).","Crescimento via IGF-1."],["4bnzl71ef","What regulates GH secretion?","Released in pulses in response to GHRH; increased by exercise, deep sleep, puberty, hypoglycemia, CKD; inhibited by somatostatin, glucose, obesity, IGF-1.","Pulsos; sono e exercício."],["1v6dror11","What is the function of ghrelin?","Stimulates hunger and GH release; produced by the stomach.","Fome."],["2ywzg2av1","What is the function of leptin?","Satiety hormone produced by adipose tissue; decreases appetite.","Saciedade."],["7ujk4fue9","What are the effects of ADH?","Regulates serum osmolality (V2 receptors: aquaporin-2 insertion in collecting duct) and blood pressure (V1 receptors: vasoconstriction).","Reabsorção de água e vasoconstrição."],["1p13c4t1w","What stimulates ADH release?","Increased plasma osmolality (main) and decreased blood volume.","Osmolalidade alta e hipovolemia."],["11wucf3g5","What is the role of oxytocin?","Uterine contraction during labor and milk letdown; social bonding.","Parto e ejeção do leite."],["15fw3gh1r","What are the effects of cortisol?","Increases blood pressure, insulin resistance, gluconeogenesis, lipolysis, proteolysis; decreases fibroblast activity, inflammation and immune responses, bone formation.","Eleva glicose e suprime imunidade."],["l82anj1bj","How does cortisol increase blood pressure?","Upregulates alpha1 receptors on arterioles (increased sensitivity to norepinephrine/epinephrine); mineralocorticoid effects at high doses.","Aumenta receptores alfa-1."],["137qx6m1w","How does cortisol suppress the immune system?","Inhibits phospholipase A2 and NF-kB, reduces IL-2, histamine release, eosinophils, lymphocytes; increases neutrophils (demargination).","Inibe NF-kB e fosfolipase A2."],["xmfd9h19x","What binds cortisol in the blood?","Corticosteroid-binding globulin (CBG).","Globulina ligadora de cortisol."],["14tnxrria","What regulates cortisol secretion?","CRH from hypothalamus stimulates ACTH, which stimulates cortisol; cortisol exerts negative feedback; circadian rhythm with morning peak.","Eixo CRH-ACTH."],["snelh9opl","What is the effect of chronic stress on cortisol?","Prolonged cortisol secretion.","Cortisol cronicamente alto."],["1uojgk74s","What are the actions of PTH?","Increases bone resorption of Ca2+ and phosphate, increases renal Ca2+ reabsorption in DCT, decreases phosphate reabsorption in PCT, increases 1-alpha-hydroxylase (calcitriol).","Reabsorve cálcio e elimina fosfato."],["1flbljj1l","Net effect of PTH on serum levels?","Increased serum Ca2+, decreased serum phosphate, increased urinary phosphate (and cAMP).","Cálcio sobe e fosfato cai."],["19wn71eca","How does PTH stimulate bone resorption?","PTH acts on osteoblasts to increase RANKL and decrease OPG, activating osteoclasts.","Via RANKL."],["rn4oqw1md","What regulates PTH secretion?","Decreased serum Ca2+ increases PTH (via calcium-sensing receptor); slight hypomagnesemia increases PTH; severe hypomagnesemia decreases PTH.","Cálcio baixo estimula."],["9bjzi04d3","What happens with intermittent vs continuous PTH?","Intermittent (teriparatide) stimulates bone formation; continuous high PTH causes bone resorption.","Intermitente forma osso."],["gpkk9015i","What are the effects of calcitonin?","Decreases bone resorption of Ca2+; less important physiologically in humans.","Reduz reabsorção óssea."],["1xaskd8og","What are the effects of calcitriol (1,25-(OH)2 vitamin D)?","Increases intestinal absorption of Ca2+ and phosphate, increases bone resorption, increases renal Ca2+ and phosphate reabsorption.","Absorve cálcio e fosfato."],["28mus11pv","What regulates calcitriol production?","Increased by PTH, decreased Ca2+, decreased phosphate; decreased by FGF23.","PTH estimula; FGF23 inibe."],["849li816a","What does FGF23 do?","Secreted by osteocytes; decreases phosphate reabsorption and calcitriol production.","Elimina fosfato."],["1pidyml1l","What fraction of plasma calcium is ionized?","About 45% ionized (active), 40% bound to albumin, 15% bound to anions.","Cerca de 45%."],["1t63mpb16","How does alkalosis affect ionized calcium?","Increases binding of Ca2+ to albumin, lowering ionized Ca2+ (can cause tetany, as in hyperventilation).","Alcalose reduz cálcio ionizado."],["d20k7u1sg","How are thyroid hormones synthesized?","Iodide uptake (Na/I symporter), oxidation and organification by thyroid peroxidase onto thyroglobulin, coupling of MIT and DIT to form T3 and T4.","Iodo, peroxidase e acoplamento."],["ssbn1m1vk","Which enzyme converts T4 to T3 in peripheral tissues?","5'-deiodinase.","5'-desiodase."],["mlj7g21cs","Which is more active, T3 or T4?","T3 (binds the nuclear receptor with higher affinity); T4 is the main secreted form.","T3 é mais ativo."],["co3vcg17j","What binds thyroid hormone in serum?","Thyroxine-binding globulin (TBG).","TBG."],["3nu8vw1t1","What happens to TBG and total T4 in pregnancy or OCP use?","Increased TBG (estrogen) increases total T4 but free T4 is normal.","TBG e T4 total sobem."],["ietlej30f","What are the effects of thyroid hormone?","Increased Na+/K+-ATPase (BMR and heat), increased beta1 receptors in heart (HR, contractility), glycogenolysis, gluconeogenesis, lipolysis, brain maturation, bone growth (with GH), increased GI motility.","Metabolismo e crescimento."],["15t80d619","What is the Wolff-Chaikoff effect?","Excess iodine temporarily inhibits thyroid peroxidase, decreasing T3/T4 production.","Excesso de iodo inibe."],["1tsntxpfg","What is the Jod-Basedow phenomenon?","Iodine-induced hyperthyroidism in a patient with iodine deficiency and autonomous nodules after iodine load (e.g., contrast).","Iodo causa hipertireoidismo."],["1q0hvz0ag","What are the major adrenal androgens?","DHEA and androstenedione (converted peripherally to testosterone and estrogen).","DHEA e androstenediona."],["10h8jfzvl","What is the rate-limiting enzyme for steroidogenesis?","Cholesterol desmolase (side-chain cleavage, CYP11A1), stimulated by ACTH; StAR protein moves cholesterol into mitochondria.","Desmolase."],["ou6p6ia22","What enzyme converts testosterone to DHT?","5-alpha-reductase.","5-alfa-redutase."],["h7shuuvq3","What enzyme converts androgens to estrogens?","Aromatase (in adipose, ovary granulosa cells).","Aromatase."],["fbndnp87e","What does 21-hydroxylase deficiency cause?","Decreased cortisol and aldosterone, increased 17-hydroxyprogesterone and androgens: hypotension, hyponatremia, hyperkalemia, virilization.","Perda de sal e virilização."],["gruczd1tg","What does 11-beta-hydroxylase deficiency cause?","Decreased cortisol and aldosterone, increased 11-deoxycorticosterone (a mineralocorticoid): hypertension, hypokalemia, virilization.","Hipertensão e virilização."],["1mardfd15","What does 17-alpha-hydroxylase deficiency cause?","Decreased cortisol and sex hormones, increased mineralocorticoids: hypertension, hypokalemia, female phenotype in XY, primary amenorrhea in XX.","Hipertensão sem androgênios."],["1cw7qgj1c","What is the mechanism of signaling for peptide hormones like insulin?","Cell surface receptors (tyrosine kinase or G-protein coupled).","Receptores de superfície."],["8kiqgv241","Which hormones act via cAMP?","FSH, LH, ACTH, TSH, CRH, hCG, ADH (V2), MSH, PTH, calcitonin, histamine (H2), glucagon, GHRH.","Hormônios via AMPc."],["8kkda123z","Which hormones act via cGMP?","ANP, BNP, nitric oxide (vasodilators).","ANP, BNP e óxido nítrico."],["1pqkbtp1w","Which hormones act via IP3 (Gq)?","GnRH, oxytocin, ADH (V1), TRH, histamine (H1), angiotensin II, gastrin.","Hormônios via IP3."],["11nxa9jkw","Which hormones act via intracellular receptors?","Vitamin D, estrogen, testosterone, T3/T4, cortisol, aldosterone, progesterone.","Esteroides e tireoide."],["1vei7huzn","Which hormones act via receptor tyrosine kinase?","Insulin, IGF-1, FGF, PDGF, EGF.","Insulina e fatores de crescimento."],["tubixt9sc","Which hormones act via nonreceptor tyrosine kinase (JAK/STAT)?","GH, prolactin, cytokines (IL-2, IL-6, IFN), erythropoietin, thrombopoietin, G-CSF.","GH, prolactina e citocinas."],["1kbv65i1f","What is the role of the 24-hydroxylase enzyme in vitamin D metabolism?","Inactivates vitamin D by converting it to 24,25-(OH)2 D3 when calcium is high.","Inativa vitamina D."],["1pzl8ha1e","What is the physiologic response to hypoglycemia?","Decreased insulin, increased glucagon, epinephrine, cortisol, and GH.","Hormônios contrarreguladores."],["egumhxqd7","What are the endocrine changes in pregnancy?","Increased hCG, hPL, estrogen, progesterone, prolactin, cortisol, TBG; insulin resistance; increased thyroid hormone needs.","Mudanças endócrinas na gestação."],["1yctduu1h","What are the endocrine effects of somatostatin analogs?","Inhibit GH, TSH, insulin, glucagon, gastrin, VIP; used for acromegaly, carcinoid, VIPoma, variceal bleeding.","Inibem vários hormônios."],["1suptn81g","What does aldosterone do?","Increases Na+ reabsorption and K+ and H+ secretion in the collecting duct (principal and intercalated cells).","Retém sódio e elimina potássio."],["1vronpuxh","What stimulates aldosterone release?","Angiotensin II, hyperkalemia, ACTH (minor).","Angiotensina II e potássio."],["1urg04l12","What does the dexamethasone suppression test assess?","Whether cortisol production can be suppressed by negative feedback (used to diagnose Cushing syndrome).","Diagnóstico de Cushing."],["17hncdk1r","What does the cosyntropin (ACTH) stimulation test assess?","Adrenal cortisol reserve; inadequate rise suggests adrenal insufficiency.","Reserva adrenal."],["hau8f5zqb","What hormone mediates the effects of GH on growth?","IGF-1 (somatomedin C), produced in the liver.","IGF-1."],["19colxmb7","What lab is used to screen for acromegaly?","Serum IGF-1 (confirm with oral glucose tolerance test: GH not suppressed).","IGF-1."],["1dj55zx1v","What is the role of incretins?","GLP-1 and GIP released by gut after oral glucose increase insulin release (oral glucose gives more insulin than IV glucose).","Glicose oral libera mais insulina."]]}];
